window.ASN_CARDS = [{"id":1,"category":"Introduction","phrase":"Thank you for stopping by.","japanese":"お立ち寄りありがとうございます。","example":"Thank you for stopping by our poster."},{"id":2,"category":"Introduction","phrase":"Our poster asks whether ...","japanese":"私たちのポスターでは…かどうかを検討しています。","example":"Our poster asks whether proteinuria changes the association between uric acid and eGFR decline."},{"id":3,"category":"Introduction","phrase":"Previous findings have been inconsistent.","japanese":"これまでの研究結果は一貫していません。","example":"Previous findings on this interaction have been inconsistent."},{"id":4,"category":"Introduction","phrase":"It remains unclear whether ...","japanese":"…かどうかはまだ明らかではありません。","example":"It remains unclear whether proteinuria modifies the uric acid–eGFR association."},{"id":5,"category":"Introduction","phrase":"We aimed to examine ...","japanese":"私たちは…を検討することを目的としました。","example":"We aimed to examine the association between baseline uric acid and annual eGFR change."},{"id":6,"category":"Introduction","phrase":"according to proteinuria status","japanese":"蛋白尿の有無別に。","example":"We estimated eGFR slopes according to baseline proteinuria status."},{"id":7,"category":"Introduction","phrase":"Let me start with the study population.","japanese":"まず研究対象者から説明します。","example":"Let me start with the study population shown in Figure 1."},{"id":8,"category":"Introduction","phrase":"Here is the main result.","japanese":"これが主な結果です。","example":"Here is the main result: the curves differ by proteinuria status."},{"id":9,"category":"Introduction","phrase":"The key message is that ...","japanese":"重要な結論は…ということです。","example":"The key message is that higher uric acid was linked to faster decline primarily among participants with proteinuria."},{"id":10,"category":"Introduction","phrase":"Please feel free to interrupt me.","japanese":"いつでも途中でご質問ください。","example":"Please feel free to interrupt me if any part of the figure is unclear."},{"id":11,"category":"Cohort","phrase":"a community-based cohort","japanese":"地域住民を対象としたコホート。","example":"We analyzed a community-based cohort from coastal Iwate, Japan."},{"id":12,"category":"Cohort","phrase":"be drawn from the RIAS study","japanese":"RIAS研究から抽出される。","example":"These participants were drawn from the RIAS study."},{"id":13,"category":"Cohort","phrase":"begin six months after the disaster","japanese":"震災の6か月後に始まる。","example":"The baseline survey began about six months after the 2011 earthquake and tsunami."},{"id":14,"category":"Cohort","phrase":"be followed annually through 2020","japanese":"2020年まで毎年追跡される。","example":"Participants were followed annually through 2020."},{"id":15,"category":"Cohort","phrase":"provide written informed consent","japanese":"文書による同意を提供する。","example":"A total of 10,475 people provided written informed consent."},{"id":16,"category":"Cohort","phrase":"withdraw consent before data release","japanese":"データ公開前に同意を撤回する。","example":"One hundred nine participants withdrew consent before data release."},{"id":17,"category":"Cohort","phrase":"be excluded for missing follow-up data","japanese":"追跡データの欠損で除外される。","example":"We excluded 1,334 people for missing follow-up eGFR data."},{"id":18,"category":"Cohort","phrase":"be excluded for a history of gout","japanese":"痛風の既往により除外される。","example":"People with a history of gout or current urate-lowering therapy were excluded."},{"id":19,"category":"Cohort","phrase":"include adults aged 20 or older","japanese":"20歳以上の成人を含む。","example":"The analysis included adults aged 20 or older."},{"id":20,"category":"Cohort","phrase":"the final analytic cohort","japanese":"最終的な解析対象集団。","example":"The final analytic cohort comprised 8,266 participants."},{"id":21,"category":"Measures","phrase":"baseline serum uric acid","japanese":"ベースライン時の血清尿酸。","example":"Baseline serum uric acid was the exposure of interest."},{"id":22,"category":"Measures","phrase":"annual eGFR slope","japanese":"年間のeGFR傾き。","example":"The annual eGFR slope was our outcome."},{"id":23,"category":"Measures","phrase":"baseline dipstick proteinuria","japanese":"ベースライン時の尿試験紙による蛋白尿。","example":"We assessed baseline dipstick proteinuria as a potential effect modifier."},{"id":24,"category":"Measures","phrase":"trace or greater on dipstick","japanese":"尿試験紙で±以上。","example":"In the main analysis, proteinuria meant trace or greater on dipstick."},{"id":25,"category":"Measures","phrase":"a single spot urine sample","japanese":"単回の随時尿検体。","example":"Proteinuria was measured using a single daytime spot urine sample."},{"id":26,"category":"Measures","phrase":"be present in 371 participants","japanese":"371人に認められる。","example":"Proteinuria was present in 371 participants, or 4.5 percent."},{"id":27,"category":"Measures","phrase":"a mean follow-up of 7.1 years","japanese":"平均7.1年の追跡。","example":"The cohort had a mean follow-up of 7.1 years."},{"id":28,"category":"Measures","phrase":"a mean age of 61.7 years","japanese":"平均年齢61.7歳。","example":"The participants had a mean age of 61.7 years."},{"id":29,"category":"Measures","phrase":"a higher mean uric acid level","japanese":"より高い平均尿酸値。","example":"Mean uric acid was 5.8 with proteinuria versus 5.1 without it."},{"id":30,"category":"Measures","phrase":"a lower baseline eGFR","japanese":"より低いベースラインeGFR。","example":"Baseline eGFR was 68.0 with proteinuria versus 78.5 without it."},{"id":31,"category":"Methods","phrase":"use linear mixed-effects models","japanese":"線形混合効果モデルを用いる。","example":"We used linear mixed-effects models to estimate annual eGFR change."},{"id":32,"category":"Methods","phrase":"account for repeated eGFR measurements","japanese":"eGFRの反復測定を考慮する。","example":"The model accounted for repeated eGFR measurements within each participant."},{"id":33,"category":"Methods","phrase":"random intercepts and random slopes","japanese":"ランダム切片とランダム傾き。","example":"We included participant-specific random intercepts and random slopes for time."},{"id":34,"category":"Methods","phrase":"model uric acid continuously","japanese":"尿酸を連続変数としてモデル化する。","example":"We modeled uric acid continuously rather than using only categories."},{"id":35,"category":"Methods","phrase":"allow for a nonlinear association","japanese":"非線形の関連を許容する。","example":"Restricted cubic splines allowed for a nonlinear association."},{"id":36,"category":"Methods","phrase":"restricted cubic splines","japanese":"制限付き三次スプライン。","example":"We used restricted cubic splines with three knots for uric acid."},{"id":37,"category":"Methods","phrase":"at the 10th, 50th, and 90th percentiles","japanese":"10、50、90パーセンタイルに。","example":"The spline knots were placed at the 10th, 50th, and 90th percentiles."},{"id":38,"category":"Methods","phrase":"test the three-way interaction","japanese":"三者間交互作用を検定する。","example":"We tested the interaction among time, uric acid, and proteinuria."},{"id":39,"category":"Methods","phrase":"adjust for baseline covariates","japanese":"ベースラインの共変量で調整する。","example":"We adjusted for baseline covariates such as age, diabetes, and eGFR."},{"id":40,"category":"Methods","phrase":"prespecified subgroup analyses","japanese":"事前に設定したサブグループ解析。","example":"We prespecified analyses by age, sex, BMI, blood pressure, diabetes, and eGFR."},{"id":41,"category":"Findings","phrase":"This figure shows adjusted eGFR slopes.","japanese":"この図は調整済みeGFR傾きを示します。","example":"Figure 2 shows adjusted eGFR slopes across serum uric acid levels."},{"id":42,"category":"Findings","phrase":"on the horizontal axis","japanese":"横軸上に。","example":"On the horizontal axis, we show serum uric acid in milligrams per deciliter."},{"id":43,"category":"Findings","phrase":"on the vertical axis","japanese":"縦軸上に。","example":"On the vertical axis, we show annual eGFR change."},{"id":44,"category":"Findings","phrase":"the shaded areas represent ...","japanese":"網掛け部分は…を示します。","example":"The shaded areas represent 95 percent confidence intervals."},{"id":45,"category":"Findings","phrase":"show little variation across uric acid levels","japanese":"尿酸値が変わってもほとんど変動しない。","example":"Without proteinuria, the eGFR slope showed little variation across uric acid levels."},{"id":46,"category":"Findings","phrase":"be close to minus 1.11 per year","japanese":"年間約−1.11である。","example":"The mean slope without proteinuria was close to minus 1.11 per year."},{"id":47,"category":"Findings","phrase":"show no clear association","japanese":"明確な関連を示さない。","example":"We saw no clear association in the proteinuria-negative group, with a P value of 0.220."},{"id":48,"category":"Findings","phrase":"a nonlinear association","japanese":"非線形の関連。","example":"Among participants with proteinuria, the association was nonlinear."},{"id":49,"category":"Findings","phrase":"be least negative around 5.0 milligrams per deciliter","japanese":"約5.0 mg/dLで負の程度が最も小さい。","example":"With proteinuria, the eGFR slope was least negative around 5.0 milligrams per deciliter."},{"id":50,"category":"Findings","phrase":"an estimated slope of minus 1.27","japanese":"推定傾き−1.27。","example":"At 5.0 milligrams per deciliter, the estimated slope was minus 1.27 per year."},{"id":51,"category":"Findings","phrase":"become progressively more negative","japanese":"徐々により負の値になる。","example":"Above 5.0, the estimated eGFR slope became progressively more negative."},{"id":52,"category":"Findings","phrase":"reach minus 2.04 at 7.8","japanese":"7.8で−2.04に達する。","example":"At 7.8 milligrams per deciliter, the slope reached minus 2.04 per year."},{"id":53,"category":"Findings","phrase":"a steeper decline at higher uric acid levels","japanese":"尿酸値が高いほどより急速な低下。","example":"With proteinuria, higher uric acid levels were linked to a steeper eGFR decline."},{"id":54,"category":"Findings","phrase":"proteinuria modified the association","japanese":"蛋白尿は関連性を修飾しました。","example":"Proteinuria modified the association between uric acid and eGFR slope."},{"id":55,"category":"Findings","phrase":"P for interaction was below 0.001","japanese":"交互作用のP値は0.001未満でした。","example":"The two patterns differed, with a P for interaction below 0.001."},{"id":56,"category":"Subgroups","phrase":"compare the slopes between groups","japanese":"群間で傾きを比較する。","example":"Figure 3 compares eGFR slopes between the proteinuria groups."},{"id":57,"category":"Subgroups","phrase":"positive minus negative","japanese":"陽性群から陰性群を引いた値。","example":"We calculated the difference as the slope with proteinuria minus the slope without it."},{"id":58,"category":"Subgroups","phrase":"a negative difference means ...","japanese":"負の差は…を意味します。","example":"A negative difference means faster eGFR decline in the proteinuria-positive group."},{"id":59,"category":"Subgroups","phrase":"become more negative as uric acid increases","japanese":"尿酸値が上がるにつれて差がより負になる。","example":"Across most subgroups, the difference became more negative as uric acid increased."},{"id":60,"category":"Subgroups","phrase":"a prespecified subgroup","japanese":"事前に設定したサブグループ。","example":"Baseline eGFR was one of six prespecified subgroup factors."},{"id":61,"category":"Subgroups","phrase":"correct for multiple comparisons","japanese":"多重比較を補正する。","example":"We used Bonferroni correction for the six subgroup interaction tests."},{"id":62,"category":"Subgroups","phrase":"remain significant after correction","japanese":"補正後も有意である。","example":"Only the baseline eGFR interaction remained significant after correction."},{"id":63,"category":"Subgroups","phrase":"an adjusted P value below 0.001","japanese":"補正後のP値が0.001未満。","example":"For baseline eGFR, the adjusted P value for interaction was below 0.001."},{"id":64,"category":"Subgroups","phrase":"with baseline eGFR below 60","japanese":"ベースラインeGFRが60未満では。","example":"With baseline eGFR below 60, the proteinuric group declined faster throughout the plotted range."},{"id":65,"category":"Subgroups","phrase":"interpret this subgroup with caution","japanese":"このサブグループは慎重に解釈する。","example":"The persistent gap suggests higher risk with proteinuria throughout the displayed uric acid range."},{"id":66,"category":"Sensitivity","phrase":"a stricter proteinuria threshold","japanese":"より厳しい蛋白尿の閾値。","example":"We repeated the analysis using a stricter proteinuria threshold."},{"id":67,"category":"Sensitivity","phrase":"one-plus or greater on dipstick","japanese":"尿試験紙で1＋以上。","example":"In the sensitivity analysis, proteinuria meant one-plus or greater on dipstick."},{"id":68,"category":"Sensitivity","phrase":"classify 146 participants as positive","japanese":"146人を陽性に分類する。","example":"This stricter cutoff classified 146 participants as proteinuria-positive."},{"id":69,"category":"Sensitivity","phrase":"a qualitatively similar pattern","japanese":"定性的に同様の傾向。","example":"The sensitivity analysis showed a qualitatively similar pattern."},{"id":70,"category":"Sensitivity","phrase":"restrict the analysis to the overall cohort","japanese":"解析を全体集団に限定する。","example":"We restricted this sensitivity analysis to the overall cohort because few participants were positive."},{"id":71,"category":"Interpretation","phrase":"may identify a higher-risk group","japanese":"リスクの高い群を見分ける手がかりとなり得る。","example":"Proteinuria may identify a group in which elevated uric acid is more prognostically relevant."},{"id":72,"category":"Interpretation","phrase":"a context-dependent prognostic marker","japanese":"状況によって予後的意義が異なる指標。","example":"Serum uric acid may be a context-dependent prognostic marker."},{"id":73,"category":"Interpretation","phrase":"proteinuria may mark kidney injury","japanese":"蛋白尿は腎障害を示しているかもしれない。","example":"Proteinuria may mark underlying kidney injury, although we did not test this mechanism."},{"id":74,"category":"Interpretation","phrase":"a biologically plausible explanation","japanese":"生物学的にもっともらしい説明。","example":"Tubular injury and inflammation offer a biologically plausible explanation."},{"id":75,"category":"Interpretation","phrase":"we did not test the mechanism","japanese":"機序は検証していません。","example":"We did not test that mechanism in this cohort."},{"id":76,"category":"Interpretation","phrase":"cannot establish causality","japanese":"因果関係を証明できない。","example":"Our observational analysis cannot establish causality."},{"id":77,"category":"Interpretation","phrase":"does not establish treatment benefit","japanese":"治療効果を証明するものではない。","example":"Our finding does not establish a benefit from urate-lowering treatment."},{"id":78,"category":"Interpretation","phrase":"need confirmation in other cohorts","japanese":"他のコホートで確認が必要である。","example":"This finding needs confirmation in cohorts with quantitative albuminuria data."},{"id":79,"category":"Interpretation","phrase":"interpret the low eGFR subgroup carefully","japanese":"低eGFR群を慎重に解釈する。","example":"We interpret the low eGFR subgroup carefully because its slope difference was already negative."},{"id":80,"category":"Interpretation","phrase":"a possible clinical implication","japanese":"考えられる臨床的示唆。","example":"A possible clinical implication is to consider proteinuria when interpreting serum uric acid."},{"id":81,"category":"Limitations","phrase":"measured only at baseline","japanese":"ベースライン時のみ測定された。","example":"Uric acid and proteinuria were measured only at baseline in our analysis."},{"id":82,"category":"Limitations","phrase":"a single dipstick test","japanese":"単回の尿試験紙検査。","example":"A single dipstick test cannot establish persistent proteinuria."},{"id":83,"category":"Limitations","phrase":"misclassify low-grade albuminuria","japanese":"軽度のアルブミン尿を誤分類する。","example":"Dipstick testing may misclassify low-grade albuminuria."},{"id":84,"category":"Limitations","phrase":"residual confounding","japanese":"残余交絡。","example":"Residual confounding by factors such as diet or medication is possible."},{"id":85,"category":"Limitations","phrase":"selection bias from missing follow-up","japanese":"追跡データ欠損に伴う選択バイアス。","example":"Excluding people without follow-up eGFR data may cause selection bias."},{"id":86,"category":"Limitations","phrase":"wide confidence intervals at the extremes","japanese":"両端で広い信頼区間。","example":"The confidence intervals were wider at the extremes of the uric acid range."},{"id":87,"category":"Limitations","phrase":"limited subgroup precision","japanese":"サブグループ推定の精度に限界がある。","example":"The small proteinuria-positive group limits subgroup precision."},{"id":88,"category":"Limitations","phrase":"creatinine-based eGFR","japanese":"クレアチニンに基づくeGFR。","example":"Creatinine-based eGFR can be affected by factors other than filtration."},{"id":89,"category":"Limitations","phrase":"limited generalizability","japanese":"一般化可能性に限界がある。","example":"The disaster-affected regional cohort may have limited generalizability."},{"id":90,"category":"Limitations","phrase":"an observational association","japanese":"観察された関連性。","example":"An observational association should not be interpreted as a treatment effect."},{"id":91,"category":"Q&A","phrase":"Thank you for that question.","japanese":"ご質問ありがとうございます。","example":"Thank you for that question about our proteinuria definition."},{"id":92,"category":"Q&A","phrase":"To clarify, we defined ...","japanese":"明確にすると、私たちは…と定義しました。","example":"To clarify, we defined proteinuria as trace or greater in the main analysis."},{"id":93,"category":"Q&A","phrase":"We chose this cutoff a priori.","japanese":"この閾値は事前に設定しました。","example":"We chose this cutoff a priori and tested one-plus or greater separately."},{"id":94,"category":"Q&A","phrase":"A negative value here indicates ...","japanese":"ここで負の値は…を示します。","example":"A negative value here indicates faster decline in the proteinuric group."},{"id":95,"category":"Q&A","phrase":"Only one factor showed heterogeneity.","japanese":"異質性を示した因子は一つだけでした。","example":"Only baseline eGFR showed significant heterogeneity after Bonferroni correction."},{"id":96,"category":"Q&A","phrase":"We cannot determine that from these data.","japanese":"このデータからは判断できません。","example":"We cannot determine whether uric acid itself caused eGFR decline from these data."},{"id":97,"category":"Q&A","phrase":"That was not measured repeatedly.","japanese":"それは繰り返し測定していません。","example":"Uric acid was measured at baseline, so we cannot address changes over time."},{"id":98,"category":"Q&A","phrase":"The result was similar with a stricter cutoff.","japanese":"より厳しい閾値でも結果は同様でした。","example":"The result was similar with a stricter cutoff of one-plus or greater."},{"id":99,"category":"Q&A","phrase":"That mechanism remains a hypothesis.","japanese":"その機序は仮説にとどまります。","example":"That mechanism remains a hypothesis; we did not measure tubular inflammation."},{"id":100,"category":"Q&A","phrase":"Thank you for the suggestion.","japanese":"ご提案ありがとうございます。","example":"Thank you for the suggestion to validate this in another cohort."}];
